package de.ostms.lc.audit.api;
import de.ostms.lc.audit.domain.AuditEvent; import de.ostms.lc.audit.service.AuditService; import de.ostms.lc.audit.service.AuditChainService; import org.springframework.web.bind.annotation.*; import java.util.List;import org.springframework.http.*;
@RestController @RequestMapping("/api/audit") public class AuditController {private final AuditService service;public AuditController(AuditService s){service=s;}@GetMapping public List<AuditEvent> recent(){return service.recent();}
 @org.springframework.beans.factory.annotation.Autowired private AuditChainService chain;
 /** Verifies the hash chain of the current tenant and records that the check was run. */
 @GetMapping("/chain") public AuditChainService.Chain chain(org.springframework.security.core.Authentication auth){var result=chain.verifyCurrent();service.record(auth,"AUDIT_CHAIN_VERIFIED","AUDIT",null,(result.ok()?"Kette intakt":"Kette BRUCH bei Nr. "+result.firstBadSeq())+" · "+result.checked()+" Eintraege geprueft");return result;}@GetMapping(value="/export.csv",produces="text/csv")public ResponseEntity<byte[]> export(){byte[] content=service.csv();return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=Audit-Protokoll.csv").contentLength(content.length).body(content);}}
